steps.command:
set -eu
install -d -o root -g root -m 0700 /etc/nginx/tls
openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:2048 -out /etc/nginx/tls/server.key
cat > /etc/nginx/tls/expired-cert.ext <<'INFRASET_EXT'
subjectAltName=DNS:node1
basicConstraints=critical,CA:FALSE
keyUsage=critical,digitalSignature,keyEncipherment
extendedKeyUsage=serverAuth
INFRASET_EXT
openssl x509 -new \
  -key /etc/nginx/tls/server.key \
  -subj '/CN=node1' \
  -set_serial 0x01 \
  -not_before 20240101000000Z \
  -not_after 20250101000000Z \
  -extfile /etc/nginx/tls/expired-cert.ext \
  -out /etc/nginx/tls/server.crt
rm -f /etc/nginx/tls/expired-cert.ext
chown root:root /etc/nginx/tls/server.key /etc/nginx/tls/server.crt
chmod 0600 /etc/nginx/tls/server.key
chmod 0644 /etc/nginx/tls/server.crt
printf '%s\n' 'existing HTTPS content: preserve during certificate rotation' > /var/www/html/index.html
truncate -s 100M /var/www/html/continuity.bin
cat > /etc/nginx/sites-available/infraset-tls <<'INFRASET_NGINX'
server {
    listen 443 ssl;
    listen [::]:443 ssl;
    server_name node1;

    ssl_certificate     /etc/nginx/tls/server.crt;
    ssl_certificate_key /etc/nginx/tls/server.key;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_session_tickets off;

    root /var/www/html;
    index index.html;

    location = /healthz {
        default_type text/plain;
        return 200 "certificate-rotation-ready\n";
    }

    location = /continuity.bin {
        limit_rate 20k;
        try_files $uri =404;
    }
}
INFRASET_NGINX
rm -f /etc/nginx/sites-enabled/default
ln -sfn /etc/nginx/sites-available/infraset-tls /etc/nginx/sites-enabled/infraset-tls
nginx -t
systemctl enable nginx.service >/dev/null
systemctl restart nginx.service
systemctl is-active --quiet nginx.service
if openssl x509 -in /etc/nginx/tls/server.crt -checkend 0 -noout; then
  exit 1
fi
openssl x509 -in /etc/nginx/tls/server.crt -checkhost node1 -noout >/dev/null
